-- Domain 18: Business Tax & E-file | views
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 1115
CREATE VIEW public.efile_calendar WITH (security_invoker='true') AS
 SELECT f.tenant_id,
    f.id AS filing_id,
    f.form_code,
    ft.name AS form_name,
    f.state_code,
    f.tax_year,
    f.period_label,
    f.due_date,
    f.status,
    f.channel,
    f.record_count,
    f.total_amount,
    f.confirmation_number,
        CASE
            WHEN (f.status = ANY (ARRAY['accepted'::text, 'accepted_with_errors'::text, 'filed_manually'::text])) THEN 'done'::text
            WHEN ((f.due_date IS NOT NULL) AND (f.due_date < CURRENT_DATE)) THEN 'overdue'::text
            WHEN ((f.due_date IS NOT NULL) AND (f.due_date <= (CURRENT_DATE + 14))) THEN 'due_soon'::text
            ELSE 'open'::text
        END AS urgency
   FROM (public.efile_filings f
     JOIN public.efile_form_types ft ON ((ft.code = f.form_code)))
  WHERE (f.status <> 'void'::text);

